import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Target Repos — Repo = Target, Module = One Port Implementation","description":"","frontmatter":{"title":"Target Repos — Repo = Target, Module = One Port Implementation","type":"adr","date":"2026-10-15T00:00:00.000Z","status":"proposed","status_note":"Proposed — repo = target/ecosystem, module = one port implementation; extraction landed per the design table."},"headers":[],"relativePath":"handl/project/adrs/0128-target-repos.md","filePath":"vendored/handl/project/adrs/0128-target-repos.md"}`),a={name:`handl/project/adrs/0128-target-repos.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0128-target-repos-—-repo-target-module-one-port-implementation" tabindex="-1">ADR-0128: Target Repos — Repo = Target, Module = One Port Implementation <a class="header-anchor" href="#adr-0128-target-repos-—-repo-target-module-one-port-implementation" aria-label="Permalink to “ADR-0128: Target Repos — Repo = Target, Module = One Port Implementation”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong>Repo = target/ecosystem; module = one implementation of one port.</strong> A module registers one or more named targets; target name ≠ repo name.</li><li><strong>Module directories carry the specific name</strong> (<code>modules/&lt;port&gt;-&lt;specific&gt;</code>), never the generalized port name: <code>web/modules/sdkgen-webidl</code> registers <code>webidl</code>, and a second sdkgen target lands beside it.</li><li><strong>Compiler targets are one repo each</strong> — <code>dot/</code>, <code>term/</code>, <code>sexp/</code>, <code>handl/</code>, <code>web/</code> (JS), <code>native/</code> (LLVM, Cranelift) — each holding <code>modules/compile-&lt;target&gt;</code>.</li><li><strong>Platform keeps</strong> ports, core crates, kit machinery, engines, wiring, loaders, <code>host-tooling</code>, and three machinery <code>plugin-lib-*</code> (<code>handl</code>, <code>tag</code>, <code>scheduler</code>). Every other <code>plugin-lib-*</code> moves to <code>stdlib/</code>.</li><li><strong>The per-crate extraction map</strong> (26 rows of crate → repo/module) is the port plan: see the design doc; each row moves once, with its <code>.hnl</code> packages pinned to it.</li><li><strong>The platform repo is renamed <code>host/</code></strong>; <code>handl/</code> means the language target; <code>host-tooling</code> stays as the shared host contract for <code>cli/</code> and <code>lsp/</code>.</li><li><strong>Hosts sit at the top of the fan</strong>: <code>host-cli</code> and <code>host-lsp</code> declare explicit git-dependency lists, so the registries are load-bearing.</li><li><strong>Git deps bypass registries</strong>: consumers set <code>CARGO_NET_GIT_FETCH_WITH_CLI=1</code>, each repo&#39;s CI holds a read credential for its siblings, and repos flip public when external contribution matters.</li><li><strong>The <code>lang/</code> cycle is broken by injection</strong>: consumers take <code>&amp;Language</code>/a kit handle; the concrete canonical kit is assembled in <code>kit-canonical/</code> (Phase-0 work, not a late surprise).</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>The platform built every target in one graph: <code>cranelift</code> and <code>clang-sys</code>/<code>inkwell</code> sat in the default build, <code>plugin-ext-sdkgen</code> carried 205 foreign Python lines, and nothing had an ownership boundary. Repo-per-target makes each repo build only its own graph and gives every target an owner.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>Keep every target in the platform</strong> — the current state: one graph, all toolchains, no ownership.</li><li><strong>One repo per port</strong> — several targets implement one port; they would collide.</li><li><strong>Registry crates instead of git deps</strong> — the targets are private and pre-release; git revs are the honest pin.</li><li><strong>Store the kit in plugin state to break the cycle</strong> — <code>Kit</code> is <code>!Sync</code>; injection is a parameter, not a field.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>Each repo builds only its own graph; <code>cranelift</code>/<code>clang</code> leave the default build and <code>plugin-ext-sdkgen</code> loses its foreign lines.</li><li>A port change becomes a multi-PR atomic change plus a git rev bump (mitigated by tag pinning, not eliminated).</li><li><code>kit-canonical</code> gains a git dependency on <code>stdlib/</code> — a deliberate inversion: the platform depends on the stdlib package, not vice versa.</li><li>Every repo needs sibling read credentials; <code>docs/</code> stays the public hub.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li>The repos and module paths named in the extraction table (design doc).</li><li><code>.cargo/config.toml</code> — <code>net.git-fetch-with-cli = true</code>.</li><li>Each repo&#39;s <code>ci.sh</code> / bupha config — sibling read credential.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>The extraction table, the <code>0.8</code> seam measurements and the cycle analysis: <a href="./../design/0128-target-repos.html"><code>design/0128-target-repos.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};